std::vector<Point2d> intersections;
    for (size_t i = 0; i < segments.size(); ++i) {
        for (size_t j = i + 1; j < segments.size(); ++j) {
            const Segment2d& seg1 = segments[i];
            const Segment2d& seg2 = segments[j];
            Point2d p1From = seg1.p1();
            Point2d p1To = seg1.p2();
            Point2d p2From = seg2.p1();
            Point2d p2To = seg2.p2();
            double eps = 0.001;
            CK_Segment_2 cgalSeg1(CK_Point_2(p1From.x(), p1From.y()), CK_Point_2(p1To.x(), p1To.y()));
            CK_Segment_2 cgalSeg2(CK_Point_2(p2From.x(), p2From.y()), CK_Point_2(p2To.x(), p2To.y()));
            auto result = intersection(cgalSeg1, cgalSeg2);
            if (result) {
                if (const CK_Point_2* point = boost::get<CK_Point_2>(&*result)) {
                    intersections.emplace_back(point->x(), point->y());
                } else if (const CK_Segment_2* segment = boost::get<CK_Segment_2>(&*result)) {
                    // If intersection is a segment, add both endpoints
                    intersections.emplace_back(segment->source().x(), segment->source().y());
                    intersections.emplace_back(segment->target().x(), segment->target().y());
                }
            }
        }
    }
    // Remove duplicates using sorting and unique
    std::sort(intersections.begin(), intersections.end(), [](const Point2d& a, const Point2d& b) {
        if (std::abs(a.x() - b.x()) > 1e-9) return a.x() < b.x();
        return a.y() < b.y();
    });
    intersections.erase(std::unique(intersections.begin(), intersections.end(), [](const Point2d& a, const Point2d& b) {
        return std::abs(a.x() - b.x()) < 1e-9 && std::abs(a.y() - b.y()) < 1e-9;
    }), intersections.end());
    return intersections;

